import * as store from './store.js';
import {roles,isHospitalListing,freeBeds,haversine,candidates,guidance} from './model.js';
import {renderMap,clearMap} from './map.js';
import {startCamera,stopCamera,capture,readImage,analyzeBrowser} from './camera.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const date=s=>new Date(s).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});
const paths={arrow:'M5 12h14m-5-5 5 5-5 5',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',phone:'M5 3h4l2 5-3 2a15 15 0 0 0 6 6l2-3 5 2v4c0 2-2 3-4 2C9 19 5 15 3 7 2 5 3 3 5 3Z',heart:'M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-5 5 8 15 8 15S25 10 20 5Z M3 12h5l2-4 3 8 2-4h6',shield:'M12 3 3 7v5c0 5 9 10 9 10s9-5 9-10V7Z m-5 9 3 3 6-6',camera:'M8 5 6 8H3v12h18V8h-3l-2-3Z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',hospital:'M4 21V5h16v16M9 21v-5h6v5M12 7v6M9 10h6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',check:'M5 12l4 4L20 5',plus:'M12 5v14M5 12h14',activity:'M2 12h5l3-8 4 16 3-8h5',box:'M3 7l9-4 9 4v11l-9 4-9-4Z M3 7l9 5 9-5M12 12v10',truck:'M2 6h12v12H2ZM14 10h4l4 4v4h-8M8 18a2 2 0 1 1-4 0m16 0a2 2 0 1 1-4 0',file:'M5 3h9l5 5v13H5ZM14 3v6h5M8 13h8m-8 4h6',users:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3a7 7 0 0 1 14 0v3m0-17a4 4 0 0 1 0 8m3 3c3 0 3 3 3 6',volume:'M3 9h4l5-5v16l-5-5H3Z M16 8c3 2 3 6 0 8m3-11c5 4 5 10 0 14',external:'M14 3h7v7m-1-6L10 14m-1-9H3v16h16v-6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.heart}"/></svg>`;
const badge=(label,color='')=>`<span class="badge ${color}">${esc(label)}</span>`;
const statusLabel=s=>({reported:'Saved',requested:'Routing',reserved:'Reserved in app',accepted:'Reserved in app',destination_selected:'Hospital selected',en_route:'On the way',arrived:'Handover complete',discharged:'Discharged',intake:'New case',under_review:'Under review',fir_draft:'FIR draft',reference_recorded:'Reference recorded',closed:'Closed',simulated_paid:'Settlement recorded',simulated_acknowledgement:'Earlier preview acknowledgement'}[s]||String(s||'').replaceAll('_',' '));
const statusBadge=s=>badge(statusLabel(s),['requested','reroute_pending','submitted','requested'].includes(s)?'orange':s==='reported'?'blue':'');
const btn=(label,action,attrs='',kind='')=>`<button class="btn ${kind}" data-do="${action}" ${attrs}>${label}</button>`;
let state,role='patient',page='home',subtab='overview',coords=null,locationLabel='',liveHospitals=[],directoryMeta=null,directoryError='',directoryLoading=false;
let activeHospitalId='demo-north';
let addressResults=[],addressContext='nearby',addressQuery='',addressBusy=false,requestStage=1,chosenHospitalId=null,incidentKind='road_accident',aidIndex=0,voiceOn=false;
let cameraImage=null,cameraResult=null,scene=null,questions={safe:'',responsive:'',breathing:'',bleeding:''},poll=null,busy=false;
let autoRefresh=store.subscribe(()=>refresh());
const hospitalName=id=>state.hospitals.find(h=>h.id===id)?.name||'Hospital not selected';
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',6000);}
function modal(title,html,onSubmit){const d=$('#dialog');d.innerHTML=`<button class="close" aria-label="Close dialog" data-do="close">×</button><h2 id="dialog-title">${title}</h2>${html}`;d.showModal();const form=d.querySelector('form');if(form)form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(form)));d.close();}catch(e){form.querySelector('.form-error').textContent=e.message;}finally{button.disabled=false;}});}
function formEnd(label='Save'){return `<p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-do="close">Cancel</button><button type="submit" class="btn primary">${label}</button></div></form>`;}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function options(items,selected){return items.map(([value,label])=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`).join('');}
function roleName(r){return {patient:'Patient & family',hospital:'Hospital desk',dispatch:'Ambulance desk',pharmacy:'Pharmacy',police:'Police desk',government:'Administration'}[r];}
function shell(content){
 const nav=role==='patient'?[['home','Home'],['emergency','First aid'],['nearby','Find a hospital'],['journey','My cases']]:[['dashboard',role==='police'?'Case desk':'Overview'],['journey','Patient journeys'],['audit','Activity log']];
 $('#app').innerHTML=`<header><div class="header-inner"><a class="brand" href="#home" data-nav="home"><img src="/icon.svg" alt="">health<span><em>sos</em></span></a><nav class="topnav" aria-label="Main navigation">${nav.map(([key,label])=>`<button data-nav="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${label}</button>`).join('')}</nav><a href="tel:112" class="header-sos">${icon('phone')}112</a><label class="role-select"><span>Workspace</span><select id="role" aria-label="Choose workspace">${options(roles.map(r=>[r,roleName(r)]),role)}</select></label></div></header><main id="main" tabindex="-1">${content}</main><footer><span><span class="footer-brand">Health SOS</span> &nbsp;·&nbsp; <a href="https://112.gov.in/" target="_blank" rel="noopener">Emergency: 112</a></span><span class="environment-label"><span class="dot"></span> Preview environment · Hospital & police actions stay in this workspace. <button class="link-button" data-do="privacy">Connection details</button></span></footer>`;
}
const illustration=`<svg class="care-illustration" viewBox="0 0 470 210" role="img" aria-label="Illustration of a caregiver supporting a patient, with a hospital in the background"><path d="M25 187h420" stroke="#c5d5bd" stroke-width="2"/><rect x="284" y="55" width="135" height="132" rx="12" fill="#f9fbf5"/><rect x="326" y="29" width="52" height="53" rx="13" fill="#126b5d"/><path d="M352 41v29m-14-14h28" stroke="#fff" stroke-width="8"/><path d="M302 102h18m19 0h18m19 0h20m-94 23h18m19 0h18m19 0h20" stroke="#c6d8bd" stroke-width="10"/><rect x="338" y="153" width="25" height="34" fill="#dce7d5"/><circle cx="160" cy="52" r="23" fill="#dfac83"/><path d="M138 51c-5-34 47-41 48-2l-9-11-39 13" fill="#213d38"/><path d="m146 76-31 46 23 41 22-12-14-28 19-17 17 43 33-5-21-58Z" fill="#ed7959"/><path d="m141 155 1 32h-30m72-43 17 43h25" stroke="#213d38" stroke-width="17" fill="none" stroke-linecap="round"/><path d="m182 90 27 24 26-22" stroke="#dfac83" stroke-width="13" fill="none" stroke-linecap="round"/><circle cx="240" cy="73" r="20" fill="#c68762"/><path d="M221 71c0-30 45-25 40 5l-11-16Z" fill="#233f38"/><path d="m229 93-18 47 39 15 17-44-18-19" fill="#507d6b"/><path d="m234 148 14 39h25m-48-44-24 44h-21" stroke="#304b41" stroke-width="14" fill="none" stroke-linecap="round"/><path d="m250 104 16 30 17-3" stroke="#c68762" stroke-width="11" fill="none" stroke-linecap="round"/><path d="M76 188v-47m0 24c-31 0-25-37-25-37 27 0 25 37 25 37m0-8c27 0 26-33 26-33-25 0-26 33-26 33" stroke="#8da88b" stroke-width="3" fill="#c8d9bc"/><circle cx="90" cy="47" r="17" fill="#f8fbf3"/><path d="m83 47 5 5 9-10" stroke="#126b5d" stroke-width="3" fill="none"/><path d="M435 148v39m0-13c-17-2-17-25-17-25 18 0 17 25 17 25m0-12c18-3 16-26 16-26-15 1-16 26-16 26" fill="#cad9c0" stroke="#9bb195" stroke-width="2"/></svg>`;
function title(eyebrow,heading,description,actions=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1><p>${description}</p></div><div class="buttons">${actions}</div></div>`;}
function empty(text,action=''){return `<div class="empty">${icon('heart')}${text}${action?`<div class="buttons mt" style="justify-content:center">${action}</div>`:''}</div>`;}
function home(){
 const latest=state.incidents[0];
 return `<section class="hero emergency-home"><div class="hero-copy"><div class="eyebrow">Here for the next step</div><h1>Need help?<br><span>Start here.</span></h1><p>First aid, nearby hospitals, and a clear way forward.</p><div class="buttons"><a class="btn emergency big" href="tel:112">${icon('phone')} Call 112 now</a>${btn('Get first-aid help '+icon('arrow'),'navigate','data-page="emergency"','primary big')}</div><div class="hero-note">${icon('shield')}For immediate danger, call 112 first.</div></div><div class="hero-art"><div class="art-tag"><span class="dot"></span> You're not on your own</div>${illustration}<div class="art-foot">${icon('heart')}Help, one step at a time.</div></div></section><div class="quick-grid">${[['pin','Find a hospital','Search an address or use your location.','nearby'],['file','Save an incident','Location first. The rest can wait.','request'],['activity','Track my case','Hospital, transport and case updates.','journey']].map(([i,t,d,page])=>`<button class="quick-card" data-nav="${page}"><span class="quick-icon">${icon(i)}</span>${icon('arrow')}<h3>${t}</h3><p>${d}</p></button>`).join('')}</div>${latest?`<section class="card mt"><div class="card-head"><div><h3>Your latest case</h3><p>${esc(latest.id)} · ${esc(latest.address||'Location saved')}</p></div>${statusBadge(latest.status)}</div><div class="row"><div class="row-icon">${icon('hospital')}</div><div class="row-main"><strong>${esc(hospitalName(latest.hospitalId))}</strong><p>${esc(latest.name)}</p></div>${btn('View case '+icon('arrow'),'navigate','data-page="journey"','soft sm')}</div></section>`:`<section class="card pale mt home-reassurance"><div>${icon('users')}<h3>Less typing. More help.</h3></div><p>No account or patient name is needed to start.</p>${btn('Save an incident','new-incident','','soft')}</section>`}`;
}
function emergency(){
 const specs=[['safe','Is it safe to approach?','Stay clear of traffic, fire and electrical hazards.',[['yes','Yes, it is safe'],['no','No / I’m unsure']]],['responsive','Does the person respond?','Speak to them and check for a response.',[['yes','Yes'],['no','No / I’m unsure']]],['breathing','Does breathing look normal?','If breathing is absent, gasping, or uncertain, call 112 now.',[['yes','Yes'],['no','No'],['unsure','I can’t tell']]],['bleeding','Is there heavy external bleeding?','Look only at what you can see.',[['yes','Yes'],['no','No / unsure']]]];
 const urgent=questions.safe==='no'||questions.responsive==='no'||questions.breathing==='no'||questions.breathing==='unsure'||questions.bleeding==='yes';
 const next=specs.find(x=>!questions[x[0]]),g=guidance(questions),showSteps=urgent||!next;aidIndex=Math.min(aidIndex,g.steps.length-1);
 return `<div class="aid-top"><div><div class="eyebrow">First aid</div><h1>One step at a time.</h1></div><a class="btn emergency" href="tel:112">${icon('phone')} Call 112</a></div><div class="aid-layout"><section class="aid-focus card"><div class="aid-meta">${badge(showSteps?'WHAT TO DO NOW':`QUICK CHECK ${specs.indexOf(next)+1} OF 4`)}${btn(icon('volume')+(voiceOn?' Voice on':' Listen'),'aid-listen','','soft sm')}</div>${showSteps?`<div class="aid-symbol">${icon(urgent?'phone':'heart')}</div><h2>${esc(g.title)}</h2><p class="aid-instruction">${esc(g.steps[aidIndex])}</p><div class="aid-dots">${g.steps.map((_,n)=>`<i class="${n===aidIndex?'active':''}"></i>`).join('')}</div><div class="buttons aid-buttons">${aidIndex>0?btn('Previous','aid-prev'):''}${aidIndex<g.steps.length-1?btn('Next step '+icon('arrow'),'aid-next','','primary'):btn('Find a hospital '+icon('arrow'),'navigate','data-page="nearby"','primary')}</div>${btn('Start checks again','aid-reset','','link-button mt')}`:`<div class="aid-symbol">${icon(next[0]==='safe'?'shield':'heart')}</div><h2>${esc(next[1])}</h2><p class="muted">${esc(next[2])}</p><div class="answer-buttons">${next[3].map(([value,text])=>btn(text,'aid-answer',`data-question="${next[0]}" data-value="${value}"`,value==='yes'?'primary':'')).join('')}</div>${specs.indexOf(next)>0?btn('Go back','aid-back','','link-button mt'):''}`}</section><aside class="aid-side"><section class="card aid-call"><h3>Keep 112 on speaker.</h3><p>Follow the emergency dispatcher. Don’t wait to take a photo.</p><a href="tel:112" class="btn emergency w100">${icon('phone')} Call emergency services</a></section><details class="card camera-drawer" ${cameraImage?'open':''}><summary>${icon('camera')} Use camera or upload a photo <span>Optional</span></summary><p class="small muted">Image checks cannot diagnose an injury.</p><div class="camera-stage" id="camera-stage">${cameraImage?`<img src="${cameraImage}" alt="Selected image">`:`<div class="camera-empty">${icon('camera')}<p>Camera is off</p></div>`}</div><div class="camera-controls">${btn('Camera','camera-start')}${btn('Upload','camera-upload')}${cameraImage?btn('Clear','camera-clear','','sm'):''}</div><input class="visually-hidden" id="image-file" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Upload image"><div id="camera-actions" class="buttons mt">${cameraImage?btn('Check image','camera-analyze','','primary'):''}</div><div id="camera-result">${cameraMetrics()}</div><details><summary>Describe visible details</summary><label class="check"><input type="checkbox" id="ai-consent"> I agree to send this image to the configured AI provider.</label>${btn('Describe image','camera-ai','','sm')}<p id="scene-description" class="small">${scene?esc(scene):''}</p></details></details>${btn('Save incident details '+icon('arrow'),'new-incident','','soft w100')}</aside></div><p class="aid-footnote">General first-aid reference; follow professional instructions. <a href="https://www.redcross.org/take-a-class/first-aid/performing-first-aid/first-aid-steps" target="_blank" rel="noopener">Source</a></p>`;
}
function cameraMetrics(){if(!cameraResult)return '';const r=cameraResult;return `<div class="notice ${r.warnings.length?'':'green'} mt">${r.warnings.length?r.warnings.map(esc).join('<br>'):'Image quality checked. This is not an injury assessment.'}</div><details><summary>Image-quality details</summary><div class="metric-grid"><div class="metric">Lighting<strong>${r.brightness}/255</strong></div><div class="metric">Detail<strong>${r.sharpness}</strong></div><div class="metric">Size<strong>${r.width} × ${r.height}</strong></div></div><p class="tiny muted">${esc(r.engine)}</p></details>`;}
function nearby(){
 const sorted=coords?[...liveHospitals].map(h=>({...h,distance:haversine(coords,h)})).sort((a,b)=>a.distance-b.distance):[];
 return title('Nearby care','Find a hospital.','Enter an address, area or landmark. We’ll show real hospital listings.')+addressSearch('nearby')+`${coords?`<div class="location-summary"><span>${icon('pin')}<span>${esc(locationLabel)}</span></span>${btn('Change','change-address','','sm')}</div>`:''}${directoryError?`<div class="notice red" role="alert">${esc(directoryError)}</div>`:''}${directoryLoading?empty('Finding nearby hospitals…'):coords?`<div class="grid-2 grid-even mt"><div class="map-panel"><div id="hospital-map" role="region" aria-label="Map of hospitals near your selected address"></div></div><section class="hospital-list">${sorted.length?sorted.map(h=>hospitalListing(h)).join(''):empty('No named hospitals found here. Try another address or a wider area.')}</section></div><div class="directory-foot"><span>© OpenStreetMap contributors · Real listings, availability unverified.</span>${btn('Search wider area','widen','','sm')}</div>`:empty('Choose an address above, or use your current location.')}<div class="buttons mt">${btn('Save an incident','new-incident','','primary')}<a class="btn" href="tel:112">${icon('phone')} Call 112</a></div>`;
}
function addressSearch(context){
 return `<section class="card address-card"><form id="address-form" data-context="${context}"><label class="field" for="address-query">Where do you need help?</label><div class="address-input"><span>${icon('pin')}</span><input id="address-query" name="query" autocomplete="street-address" placeholder="Address, area or landmark" value="${esc(addressQuery)}" required minlength="3" maxlength="250"><button class="btn primary" type="submit" ${addressBusy?'disabled':''}>${addressBusy?'Searching…':'Find address'}</button></div></form><button class="location-button" data-do="locate" data-context="${context}">${icon('pin')} Use my current location</button>${addressResults.length?`<div class="address-results" aria-label="Matching addresses">${addressResults.map((p,n)=>`<button data-do="choose-address" data-index="${n}" data-context="${context}">${icon('pin')}<span><strong>${esc(p.name)}</strong><small>${esc(p.label)}</small></span>${icon('arrow')}</button>`).join('')}</div>`:''}<div id="address-error" class="form-error" role="alert"></div></section>`;
}
function hospitalListing(h,selectable=false){
 const safePhone=h.phone?.replace(/[^+\d,;]/g,'');
 return `<article class="hospital-result"><div class="row-icon">${icon('hospital')}</div><div class="row-main"><strong>${esc(h.name)}</strong><p>${esc(h.address||'Address available on source listing')}</p><div class="buttons"><a class="btn sm" href="https://www.google.com/maps/dir/?api=1&destination=${h.lat},${h.lon}" target="_blank" rel="noopener">Directions ${icon('external')}</a>${safePhone?`<a class="btn sm" href="tel:${esc(safePhone)}">${icon('phone')} Call</a>`:''}<a class="source-link" href="${esc(h.osm)}" target="_blank" rel="noopener">Source</a>${selectable?btn('Choose hospital','choose-hospital',`data-id="${esc(h.id)}"`,'soft sm'):''}</div></div><div class="hospital-distance">${Number(h.distance||0).toFixed(1)} km<small>straight-line</small></div></article>`;
}
function requestPage(){
 const ranked=coords?state.hospitals.filter(h=>haversine(coords,h)<30&&h.source==='OpenStreetMap'&&isHospitalListing(h.name)).map(h=>({...h,distance:haversine(coords,h)})).sort((a,b)=>a.distance-b.distance):[];
 if(!chosenHospitalId&&ranked.length)chosenHospitalId=ranked[0].id;
 const h=state.hospitals.find(h=>h.id===chosenHospitalId);
 return title('Save an incident','Help starts with a location.','You can add patient details later.',btn('Back','navigate','data-page="home"'))+`<div class="request-progress"><span class="${requestStage===1?'active':'done'}">1 &nbsp; Location</span><span class="${requestStage===2?'active':''}">2 &nbsp; Save & route</span></div>${requestStage===1||!coords?addressSearch('request'):`<div class="grid-2"><section class="card"><div class="card-head"><div><h3>${icon('pin')} Incident location</h3><p>${esc(locationLabel)}</p></div>${btn('Change','change-request-address','','sm')}</div><form id="incident-form"><label class="field">What happened?<select name="incidentType">${options([['road_accident','Road accident'],['medical','Medical emergency'],['other','Other incident']],incidentKind)}</select></label><label class="field mt">Landmark or access details <span class="muted">Optional</span><input name="landmark" placeholder="Gate number, floor, nearby shop…" maxlength="300"></label><details class="mt"><summary>Add patient details · optional</summary><div class="form-grid mt">${field('Name or label','name','','text','autocomplete="name" maxlength="100"')}${field('Contact number','contact','','tel','autocomplete="tel" maxlength="30"')}<label class="field full">What can you observe?<textarea name="notes" placeholder="Only what you can see or have been told" maxlength="1500"></textarea></label></div></details><p class="form-error" role="alert"></p><button class="btn primary big w100 mt" type="submit">${icon('check')} Save incident & reserve in app</button><p class="tiny muted">Call 112 for emergency dispatch. Saving here does not contact emergency services.</p></form></section><aside class="card hospital-choice"><div class="card-head"><div><h3>Nearest hospital</h3><p>Selected automatically from real listings.</p></div>${icon('hospital')}</div>${directoryLoading?empty('Finding hospitals…'):h?`<h2>${esc(h.name)}</h2><p>${esc(h.address||'')}</p><div class="notice green">${freeBeds(state,h)>0?'Capacity will be reserved automatically in this workspace.':'Destination will be saved. Availability needs confirmation.'}</div><p class="small muted">Call the hospital to confirm admission. Hospital desks can reroute inside the app if needed.</p><details><summary>Choose another nearby hospital</summary>${ranked.slice(0,8).map(h=>hospitalListing(h,true)).join('')}</details>`:empty('No nearby hospital is available in the directory yet. You can still save the incident and call 112.')}</aside></div>`}`;
}
function incidentCard(i,controls=false){
 const h=state.hospitals.find(h=>h.id===i.hospitalId);let actions='';
 if(controls){
  if(role==='patient')actions+=btn('Family update','family',`data-id="${i.id}"`,'sm');
  if(role==='hospital'&&['reserved','accepted','en_route','destination_selected'].includes(i.status))actions+=btn('Reroute','reroute',`data-id="${i.id}"`,'sm');
  if(role==='hospital'&&['reserved','accepted','en_route'].includes(i.status))actions+=btn('Receive patient','arrive',`data-id="${i.id}"`,'primary sm');
  if(i.status==='arrived'&&role==='hospital')actions+=btn('Create claim','claim',`data-id="${i.id}"`,'sm')+btn('Discharge','discharge',`data-id="${i.id}"`,'sm');
  if(!i.ambulanceId&&['reported','reserved','accepted','destination_selected'].includes(i.status)&&role==='dispatch')actions+=btn('Assign unit','assign',`data-id="${i.id}"`,'primary sm');
  if(['patient','hospital','dispatch','police'].includes(role)&&!state.reports.some(r=>r.incidentId===i.id))actions+=btn('Create police case','report',`data-id="${i.id}"`,'sm');
 }
 const stage=['reported','reserved','en_route','arrived'],idx=i.status==='accepted'?1:stage.indexOf(i.status);
 return `<article class="card incident-card"><div class="card-head"><div><h3>${esc(i.name)}</h3><p>${esc(i.id)} · ${date(i.createdAt)}</p></div>${statusBadge(i.status)}</div><div class="case-location">${icon('pin')}<span>${esc(i.address||'Location saved')}${i.landmark?`<small>${esc(i.landmark)}</small>`:''}</span></div>${i.notes?`<p class="small">${esc(i.notes)}</p>`:''}<div class="row"><div class="row-icon">${icon('hospital')}</div><div class="row-main"><strong>${h?esc(h.name):'Hospital not selected'}</strong><p>${i.status==='destination_selected'?'Call to confirm availability.':i.hospitalId?'Reservation saved in this app. Call to confirm external admission.':'Call 112 for emergency assistance.'}</p></div>${i.ambulanceId?badge(i.ambulanceId,'blue'):''}</div>${h?`<div class="buttons"><a class="btn sm" href="https://www.google.com/maps/dir/?api=1&destination=${h.lat},${h.lon}" target="_blank" rel="noopener">Directions ${icon('external')}</a>${h.phone?`<a class="btn sm" href="tel:${esc(h.phone.replace(/[^+\d,;]/g,''))}">Call hospital</a>`:''}</div>`:''}<div class="progress-line">${stage.map((s,n)=>`<span class="${n<=idx||i.status==='discharged'?'done':''}">${statusLabel(s)}</span>`).join('')}</div>${actions?`<div class="buttons mt">${actions}</div>`:''}<details><summary>Case timeline</summary><ol class="timeline">${i.events.map(e=>`<li><time>${date(e.at)}</time>${esc(e.text)}</li>`).join('')}</ol></details></article>`;
}
function journey(){return title('Your care','My cases','Your incident details and updates, together.',btn('New incident','new-incident','','primary'))+`<div class="stack">${state.incidents.length?state.incidents.map(i=>incidentCard(i,true)).join(''):empty('No saved cases yet.',btn('Save an incident','new-incident','','primary'))}</div>`;}
function stats(items){return `<div class="stat-grid">${items.map(([n,t,note])=>`<div class="card stat"><div class="number">${n}</div><div class="small">${t}</div>${note?`<div class="tiny muted">${note}</div>`:''}</div>`).join('')}</div>`;}
function hospital(){
 const facilities=state.hospitals.filter(h=>h.participating&&isHospitalListing(h.name)),h=facilities.find(h=>h.id===activeHospitalId)||facilities[0];
 if(!h)return title('Hospital operations','Hospital desk','Find a real hospital to set up its workspace.')+empty('No facilities loaded yet.',btn('Find a hospital','navigate','data-page="nearby"','primary'));
 activeHospitalId=h.id;const incidents=state.incidents.filter(i=>i.hospitalId===h.id),incoming=incidents.filter(i=>['reserved','accepted','en_route'].includes(i.status));
 return title('Hospital operations','Ready for the next arrival.','Reservations are automatic. Reroute only when needed.',btn('Record walk-in','walkin','','primary'))+`<section class="card facility-bar"><label class="field">Hospital workspace<select id="facility" aria-label="Hospital workspace">${options(facilities.map(h=>[h.id,h.name]),h.id)}</select></label><div><strong>${esc(h.name)}</strong><p class="small muted">${esc(h.address||'')}</p></div>${btn('Update capacity','capacity',`data-id="${h.id}"`,'sm')}</section>`+stats([[incoming.length,'Reserved incoming'],[h.occupied,'Occupied beds'],[freeBeds(state,h),'Available workspace beds'],[incidents.filter(i=>i.status==='arrived').length,'Patients received']])+`<div class="section-heading"><h2>Incoming & current patients</h2><p>${esc(h.name)}</p></div><div class="stack">${incidents.length?incidents.map(i=>incidentCard(i,true)).join(''):empty('No patients in this hospital workspace yet.')}</div>`;
}
function dispatch(){return title('Ambulance coordination','Every handover has an owner.','Assign transport, track accepted destinations, and escalate capacity changes. Assignments are recorded in this workspace.')+stats([[state.ambulances.filter(a=>a.status==='available').length,'Units available'],[state.ambulances.filter(a=>a.status!=='available').length,'Units assigned'],[state.incidents.filter(i=>i.status==='reroute_pending').length,'Reroutes pending'],[state.incidents.filter(i=>i.status==='reported').length,'Unassigned reports']])+`<section class="card"><div class="card-head"><h3>Transport units</h3>${badge('TRANSPORT UNITS','outline')}</div>${state.ambulances.map(a=>`<div class="row"><div class="row-icon">${icon('truck')}</div><div class="row-main"><strong>${esc(a.label)}</strong><p>${a.incidentId?esc(a.incidentId):'Ready for a assignment'}</p></div>${statusBadge(a.status)}</div>`).join('')}</section><div class="section-heading"><h2>Incident coordination</h2></div><div class="stack">${state.incidents.length?state.incidents.map(i=>incidentCard(i,true)).join(''):empty('No incidents to coordinate yet.',btn('Save an incident','sample','','primary'))}</div>`;}
function pharmacy(){
  const today=new Date().toISOString().slice(0,10),active=state.medicines.filter(m=>m.status==='active'&&m.expiry>=today);
  return title('Pharmacy & inventory','The right stock. Ready when needed.','Batch-level stock, expiry quarantine, approved replenishment, and documented collection.',btn('Run stock & expiry check','stock-scan','','primary'))+stats([[active.reduce((n,m)=>n+m.quantity,0),'Active stock units'],[active.filter(m=>m.quantity<m.min).length,'Batches below minimum'],[state.medicines.filter(m=>m.status==='quarantined').length,'Quarantined batches'],[state.orders.filter(o=>o.status!=='received').length,'Open supply requests']])+`<section class="card"><div class="card-head"><div><h3>Medicine & supply batches</h3><p>Batch-level stock records</p></div>${badge('BATCH TRACKING')}</div><div class="table-wrap"><table><thead><tr><th>Item / batch</th><th>Units</th><th>Expiry</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.medicines.map(m=>`<tr><td><strong>${esc(m.name)}</strong><small>${esc(m.batch)}</small></td><td>${m.quantity}<small>Minimum ${m.min}</small></td><td>${esc(m.expiry)}</td><td>${badge(m.expiry<today&&m.status==='active'?'expired':m.status,m.status==='quarantined'?'red':'')}</td><td>${m.status==='active'&&m.expiry>=today?btn('Dispense','dispense',`data-id="${m.id}"`,'sm'):'<span class="tiny muted">Dispensing blocked</span>'}</td></tr>`).join('')}</tbody></table></div></section><div class="grid-2 grid-even mt"><section class="card"><h3>Replenishment requests</h3><p class="small muted">Requests go to a supplier administration queue.</p>${state.orders.length?state.orders.map(o=>`<div class="row"><div class="row-main"><strong>${esc(state.medicines.find(m=>m.id===o.medicineId)?.name)}</strong><p>${esc(o.id)} · ${o.quantity} units</p></div>${statusBadge(o.status)}${o.status==='approved'?btn('Receive new batch','receive',`data-id="${o.id}"`,'sm'):''}</div>`).join(''):empty('Run the stock check to create low-stock requests.')}</section><section class="card"><h3>Expired stock collections</h3><p class="small muted">Quarantine → authorised collection → certificate. No physical collection is arranged.</p>${state.collections.length?state.collections.map(c=>`<div class="row"><div class="row-main"><strong>${esc(c.id)}</strong><p>${c.quantity} units · ${esc(c.certificate||'Awaiting collection')}</p></div>${statusBadge(c.status)}</div>`).join(''):empty('Expiry checks create collection requests for quarantined batches.')}</section></div>`;
}
function police(){
 const filters=[['overview','All cases'],['intake','New intake'],['fir_draft','FIR drafts'],['reference_recorded','References'],['closed','Closed']];
 const cases=state.reports.filter(r=>subtab==='overview'||r.status===subtab);
 return title('Police operations','Incident & FIR desk','Review cases, prepare drafts and keep references together.',btn('New case','new-incident','','primary'))+stats([[state.reports.filter(r=>r.status!=='closed').length,'Open cases'],[state.reports.filter(r=>r.status==='intake').length,'New intake'],[state.reports.filter(r=>r.status==='fir_draft').length,'Drafts for review'],[state.reports.filter(r=>r.officialReference).length,'References recorded']])+`<div class="tabs" role="group" aria-label="Filter police cases">${filters.map(([key,label])=>`<button data-do="subtab" data-tab="${key}" class="${subtab===key?'active':''}">${label}</button>`).join('')}</div><div class="stack">${cases.length?cases.map(r=>{const i=state.incidents.find(i=>i.id===r.incidentId);return `<article class="card police-case"><div class="card-head"><div><h3>${esc(r.id)}</h3><p>${date(r.createdAt)} · ${esc(r.incidentId)}</p></div>${statusBadge(r.status)}</div><div class="case-location">${icon('pin')}<span>${esc(i?.address||'Location in incident record')}${i?.landmark?`<small>${esc(i.landmark)}</small>`:''}</span></div><p class="case-summary">${esc(r.summary)}</p><div class="police-meta"><span><small>Station</small>${esc(r.station||'Unassigned')}</span><span><small>Officer</small>${esc(r.officer||'Unassigned')}</span><span><small>Issued reference</small>${esc(r.officialReference||'Not recorded')}</span></div>${r.officialReference?'<p class="tiny muted">Reference entered by an operator. Not verified or submitted by Health SOS.</p>':''}<div class="buttons mt">${r.status!=='closed'?btn('Review / prepare FIR draft','police-edit',`data-id="${r.id}"`,'primary sm')+btn('Record issued reference','police-reference',`data-id="${r.id}"`,'sm')+btn('Close case','police-close',`data-id="${r.id}"`,'sm'):btn('Reopen case','police-reopen',`data-id="${r.id}"`,'sm')}${btn('Download case draft','police-export',`data-id="${r.id}"`,'sm')}</div><details><summary>Case activity</summary><ol class="timeline">${(r.events||[]).map(e=>`<li><time>${date(e.at)}</time>${esc(e.text)}</li>`).join('')||'<li>Intake recorded.</li>'}</ol></details></article>`;}).join(''):empty('No cases in this queue. Road-accident incidents appear here automatically.',btn('Create a case','new-incident','','primary'))}</div><p class="tiny muted mt">FIR drafts are prepared for officer review. Official registration and police dispatch require an authorised service connection.</p>`;
}

function government(){
  const current=state.tariffs.filter(t=>!state.tariffs.some(n=>n.code===t.code&&n.state===t.state&&n.scheme===t.scheme&&n.version>t.version));
  const tabs=[['overview','Overview'],['tariffs','Tariffs & claims'],['supply','Supply & collection']];
  let content='';
  if(subtab==='overview')content=stats([[state.claims.filter(c=>c.status==='submitted').length,'Claims for review'],[state.orders.filter(o=>o.status==='requested').length,'Supply requests'],[state.reports.filter(r=>r.status==='draft').length,'Draft notifications'],[money(state.settlements.reduce((n,b)=>n+b.amount,0)),'Settlement ledger']])+`<div class="grid-2 grid-even"><section class="card pale"><h3>Operations overview.</h3><p>Review workspace tariffs, claims and supply requests in one place.</p><p>Rates shown here are workspace settings, not official government prices.</p>${btn('Review tariffs & claims','subtab','data-tab="tariffs"','soft')}</section><section class="card"><h3>Workspace records</h3><p>Export a previewnstration record or reset all incidents, stock requests and payments. This sandbox is not for real patient data.</p><div class="buttons">${btn('Export audit JSON','export','','sm')}${btn('Reset sandbox','reset','','danger sm')}</div></section></div><div class="section-heading"><h2>Recent activity</h2></div>${auditTable(state.audit.slice(0,8))}`;
  if(subtab==='tariffs')content=`<div class="grid-2 grid-even"><section class="card"><div class="card-head"><div><h3>Current tariffs</h3><p>Versioned rates · INR</p></div>${btn('Add / revise','tariff','','sm')}</div>${current.map(t=>`<div class="row"><div class="row-main"><strong>${esc(t.name)}</strong><p>${esc(t.code)} · ${esc(t.state)} · v${t.version}<br>${esc(t.scheme)}</p></div><strong>${money(t.amount)}</strong></div>`).join('')}</section><section class="card"><div class="card-head"><div><h3>Weekly settlement ledger</h3><p>Only approved claims enter a batch.</p></div></div><p>Approved balance: <strong>${money(state.claims.filter(c=>c.status==='approved').reduce((n,c)=>n+c.amount,0))}</strong></p>${btn('Run weekly settlement','settle','','primary sm')}<p class="tiny muted">Manual trigger for previewnstration. No bank transfers, funds, or scheduled payout service.</p>${state.settlements.map(b=>`<div class="row"><div class="row-main"><strong>${esc(b.id)}</strong><p>${date(b.createdAt)} · ${b.claimIds.length} claims<br>${b.transfers.map(t=>`${esc(hospitalName(t.hospitalId))}: ${money(t.amount)}`).join('<br>')}</p></div>${money(b.amount)}</div>`).join('')}</section></div><section class="card mt"><h3>Claims review</h3>${state.claims.length?`<div class="table-wrap"><table><thead><tr><th>Claim / incident</th><th>Tariff snapshot</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.claims.map(c=>`<tr><td>${esc(c.id)}<small>${esc(c.incidentId)} · ${esc(hospitalName(c.hospitalId))}</small></td><td>${esc(c.tariff.name)}<small>v${c.tariff.version} · ${esc(c.tariff.scheme)}</small></td><td>${money(c.amount)}</td><td>${statusBadge(c.status)}</td><td>${c.status==='submitted'?btn('Approve','approve-claim',`data-id="${c.id}"`,'sm'):''}</td></tr>`).join('')}</tbody></table></div>`:empty('Hospital teams can create a claim after recording patient arrival.')}</section>`;
  if(subtab==='supply')content=`<div class="notice">Government supplier and disposal activities are simulated. Replacement depends on procurement terms; no free replacement is implied.</div><div class="grid-2 grid-even"><section class="card"><h3>Supplier approval queue</h3>${state.orders.length?state.orders.map(o=>`<div class="row"><div class="row-main"><strong>${esc(state.medicines.find(m=>m.id===o.medicineId)?.name)}</strong><p>${esc(o.id)} · ${o.quantity} units</p></div>${statusBadge(o.status)}${o.status==='requested'?btn('Approve supply','approve-order',`data-id="${o.id}"`,'primary sm'):''}</div>`).join(''):empty('Run a stock check in the pharmacy workspace to generate requests.')}</section><section class="card"><h3>Authorised collection queue</h3>${state.collections.length?state.collections.map(c=>`<div class="row"><div class="row-main"><strong>${esc(c.id)}</strong><p>${c.quantity} units · ${esc(c.certificate||'No certificate yet')}</p></div>${statusBadge(c.status)}${c.status!=='disposed'?btn('Record disposal','dispose',`data-id="${c.id}"`,'sm'):''}</div>`).join(''):empty('No collection requests yet.')}</section></div>`;
  return title('Administration','See the system. Keep it accountable.','Manage agreement rates, supply requests, incident notifications, and auditable claim settlement.')+`<div class="tabs" role="group" aria-label="Administration sections">${tabs.map(([key,label])=>`<button data-do="subtab" data-tab="${key}" class="${subtab===key?'active':''}">${label}</button>`).join('')}</div>${content}`;
}
function auditTable(events){return `<section class="card"><div class="table-wrap"><table><thead><tr><th>When</th><th>Workspace</th><th>Action</th><th>Reference / detail</th></tr></thead><tbody>${events.map(e=>`<tr><td class="tiny">${date(e.at)}</td><td>${esc(e.role)}</td><td class="audit-action">${esc(e.action)}</td><td class="small">${esc(e.detail)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function guide(){return home();}
function render(){clearMap();let content;if(page==='home')content=home();else if(page==='emergency')content=emergency();else if(page==='nearby')content=nearby();else if(page==='request')content=requestPage();else if(page==='journey')content=journey();else if(page==='guide')content=guide();else if(page==='audit')content=title('An accountable care journey','Activity log','Each successful action records its role, timestamp and reference.')+auditTable(state.audit);else content=({hospital,dispatch,pharmacy,government,police}[role]||home)();if((page==='journey'||(page==='dashboard'&&role==='hospital'))&&state.appointments.length)content+=appointmentList();shell(content);if(page==='nearby'&&coords)renderMap(coords,liveHospitals);}
async function refresh(){if(busy||$('#dialog')?.open||page==='emergency'||document.activeElement?.matches('input,select,textarea'))return;try{const next=await store.read();if(next.revision!==state.revision){state=next;render();}}catch{}}
function navigate(next){if(page==='emergency'&&next!=='emergency'){stopCamera();cameraImage=null;cameraResult=null;scene=null;if('speechSynthesis'in window)speechSynthesis.cancel();}if(next==='request'){requestStage=coords?2:1;addressContext='request';}page=next;history.replaceState(null,'','#'+page);render();window.scrollTo({top:0,behavior:'instant'});}
async function mutate(action,payload,message='Saved.'){const out=await store.act(action,payload,role);state=out.state;render();toast(message);return out.result;}
function newIncident(){navigate('request');}
async function searchHospitals(lat,lon,radius=8000){
 if(!Number.isFinite(lat)||Math.abs(lat)>90||!Number.isFinite(lon)||Math.abs(lon)>180)throw Error('Choose a valid address first.');
 coords={lat,lon};directoryLoading=true;directoryError='';liveHospitals=[];directoryMeta=null;render();
 try{const data=await store.nearby(lat,lon,radius);liveHospitals=data.hospitals;directoryMeta={...data,lat,lon};try{sessionStorage.setItem('health-sos-directory',JSON.stringify(directoryMeta));}catch{}const out=await store.act('directory.sync',{hospitals:data.hospitals},role);state=out.state;toast(`${data.hospitals.length} nearby hospital listings found.`);}catch(e){directoryError=e.message;toast(e.message,true);}finally{directoryLoading=false;if(['nearby','request'].includes(page))render();}
}
async function locate(context='nearby'){
 if(!navigator.geolocation)throw Error('Your browser cannot share location. Search an address instead.');
 toast('Allow location access when your browser asks.');
 const pos=await new Promise((ok,no)=>navigator.geolocation.getCurrentPosition(ok,no,{enableHighAccuracy:true,timeout:15000,maximumAge:60000}));
 const {latitude:lat,longitude:lon}=pos.coords;let place;
 try{place=await store.addressAt(lat,lon);}catch{place={lat,lon,label:'Current device location',name:'Current location'};}
 await selectAddress(place,context);
}
async function selectAddress(place,context){
 coords={lat:place.lat,lon:place.lon};locationLabel=place.label;addressQuery=place.name||place.label;addressResults=[];chosenHospitalId=null;
 try{sessionStorage.setItem('health-sos-location',JSON.stringify({...coords,label:locationLabel,name:addressQuery}));}catch{}
 if(context==='request'){page='request';requestStage=2;}else page='nearby';
 await searchHospitals(coords.lat,coords.lon);
}
function speakCurrent(){if(!('speechSynthesis'in window))return;const g=guidance(questions),urgent=questions.safe==='no'||questions.responsive==='no'||questions.breathing==='no'||questions.breathing==='unsure'||questions.bleeding==='yes';const specs=[['safe','Is it safe to approach?'],['responsive','Does the person respond?'],['breathing','Does breathing look normal?'],['bleeding','Is there heavy external bleeding?']];const next=specs.find(x=>!questions[x[0]]);const text=urgent||!next?g.steps[Math.min(aidIndex,g.steps.length-1)]:next[1];speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-IN';utterance.rate=.9;speechSynthesis.speak(utterance);}
function appointmentList(){return `<section class="card mt"><div class="card-head"><h3>Outpatient appointment requests</h3>${badge('OUTPATIENT CALENDAR','outline')}</div>${state.appointments.map(a=>`<div class="row"><div class="row-icon">${icon('clock')}</div><div class="row-main"><strong>${esc(a.name)} · ${esc(a.department)}</strong><p>${esc(hospitalName(a.hospitalId))} · ${date(a.when)}</p></div>${statusBadge(a.status)}${role==='hospital'&&a.status==='requested'?btn('Confirm slot','confirm-appointment',`data-id="${a.id}"`,'sm'):''}</div>`).join('')}</section>`;}
async function doAction(action,el){const id=el.dataset.id;
  switch(action){
    case 'close':$('#dialog').close();break;
    case 'navigate':navigate(el.dataset.page);break;
    case 'subtab':subtab=el.dataset.tab;render();break;
    case 'appointment':modal('Request a OPD appointment',`<p>For non-emergency scheduling only. Choose a hospital and time. These appointment records belong to the preview workspace.</p><form><div class="form-grid">${field('Patient label','name','Patient','text','required')}<label class="field">Hospital<select name="hospitalId">${options(state.hospitals.map(h=>[h.id,h.name]))}</select></label>${field('Department','department','General consultation','text','required')}${field('Requested time','when','','datetime-local','required')}</div>${formEnd('Request appointment')}`,async p=>{await mutate('appointment.create',p);navigate('journey');});break;
    case 'confirm-appointment':await mutate('appointment.confirm',{id},'Appointment confirmed.');break;
    case 'family':modal('Prepare a family update',`<p>This creates a message for you to copy and send yourself. No message is sent automatically.</p><form><label class="check"><input name="consent" type="checkbox" required>I have permission to prepare this patient update.</label>${formEnd('Prepare update')}`,async p=>{const text=await mutate('family.share',{id,consent:!!p.consent},'Family update prepared; nothing sent.');setTimeout(()=>modal('Family update — ready to copy',`<label class="field">Select and copy this message<textarea rows="5" readonly>${esc(text)}</textarea></label><p>Share only with someone authorised to receive this information.</p>`),0);});break;
    case 'sample':newIncident();break;
    case 'new-incident':newIncident();break;
    case 'choose-address':await selectAddress(addressResults[Number(el.dataset.index)],el.dataset.context||'nearby');break;
    case 'change-address':coords=null;addressResults=[];render();document.querySelector('#address-form input')?.focus();break;
    case 'change-request-address':requestStage=1;addressContext='request';addressResults=[];render();break;
    case 'choose-hospital':chosenHospitalId=id;render();break;
    case 'widen':if(!coords)throw Error('Choose an address first.');await searchHospitals(coords.lat,coords.lon,15000);break;
    case 'aid-answer':questions[el.dataset.question]=el.dataset.value;aidIndex=0;render();if(voiceOn)speakCurrent();break;
    case 'aid-next':aidIndex++;render();if(voiceOn)speakCurrent();break;
    case 'aid-prev':aidIndex=Math.max(0,aidIndex-1);render();if(voiceOn)speakCurrent();break;
    case 'aid-reset':questions={safe:'',responsive:'',breathing:'',bleeding:''};aidIndex=0;render();break;
    case 'aid-back':{const keys=['safe','responsive','breathing','bleeding'];const first=keys.findIndex(k=>!questions[k]);questions[keys[Math.max(0,first-1)]]='';render();break;}
    case 'aid-listen':voiceOn=!voiceOn;if(voiceOn)speakCurrent();else if('speechSynthesis'in window)speechSynthesis.cancel();render();break;

    case 'locate':await locate(el.dataset.context||'nearby');break;
    case 'capacity':{const h=state.hospitals.find(h=>h.id===id);modal('Update staffed capacity',`<p>Set the capacity used by this workspace. Existing reservations are counted automatically.</p><form><div class="form-grid">${field('Staffed beds','beds',h.beds,'number','min="0" max="1000" required')}${field('Occupied beds','occupied',h.occupied,'number','min="0" max="1000" required')}</div>${formEnd('Update capacity')}`,p=>mutate('hospital.capacity',{hospitalId:id,...p}));break;}
    case 'walkin':modal('Record a walk-in arrival',`<p>A walk-in uses the same capacity ledger as incoming patients. Clinical staff determine priority.</p><form><label class="field">Hospital<select name="hospitalId">${options(state.hospitals.filter(h=>h.participating).map(h=>[h.id,h.name]),activeHospitalId)}</select></label>${formEnd('Record arrival')}`,p=>mutate('hospital.walkin',p,'Walk-in recorded. Review any capacity conflicts.'));break;
    case 'reroute':{const i=state.incidents.find(i=>i.id===id),hs=candidates(state,i);if(!hs.length)throw Error('No suitable alternative. Current destination retained; escalate to dispatcher.');modal('Reroute patient',`<p>The nearest alternative with workspace capacity is suggested. Confirm to transfer the in-app reservation immediately. External admission still needs confirmation.</p><form><label class="field">Suggested alternative<select name="hospitalId">${options(hs.map(h=>[h.id,`${h.name} · ${h.distance.toFixed(1)} km straight-line`]))}</select></label>${formEnd('Confirm reroute')}`,p=>mutate('incident.reroute',{id,...p},'Reservation transferred to the new hospital in this workspace.'));break;}
    case 'assign':{const available=state.ambulances.filter(a=>a.status==='available');if(!available.length)throw Error('No available units.');modal('Assign transport',`<p>Choose a unit for this journey.</p><form><label class="field">Available unit<select name="ambulanceId">${options(available.map(a=>[a.id,a.label]))}</select></label>${formEnd('Assign unit')}`,p=>mutate('dispatch.assign',{id,...p}));break;}
    case 'arrive':modal('Receive the patient handover',`<p>Confirm reception by responsible staff. The ambulance becomes available and the capacity hold becomes an occupied bed.</p><form>${field('Receiving staff label','receivedBy','Receiving nurse','text','required maxlength="80"')}${formEnd('Confirm handover')}`,p=>mutate('incident.arrive',{id,...p}));break;
    case 'discharge':await mutate('incident.discharge',{id},'Preview discharge recorded; occupied capacity released.');break;
    case 'report':{const i=state.incidents.find(i=>i.id===id);modal('Draft an incident notification',`<p>No FIR is filed. No police or emergency authority is contacted. Bystander identity is not required.</p><form><label class="field">Unverified incident summary<textarea name="summary" required maxlength="1500">${esc(i.notes||'Accident notification; circumstances require verification.')}</textarea></label>${formEnd('Save draft')}`,p=>mutate('report.create',{id,...p}));break;}
    case 'police-edit':{const r=state.reports.find(r=>r.id===id);modal('Review case & FIR draft',`<p>Prepare the record for officer review. Saving does not file an FIR.</p><form><div class="form-grid">${field('Police station','station',r.station||'','text','maxlength="200"')}${field('Assigned officer','officer',r.officer||'','text','maxlength="200"')}<label class="field full">Incident summary<textarea name="summary" required maxlength="1500">${esc(r.summary)}</textarea></label><label class="field full">FIR draft / officer notes<textarea name="firDraft" rows="7" maxlength="8000" placeholder="Record facts supplied by the complainant. Review before official submission.">${esc(r.firDraft||'')}</textarea></label></div>${formEnd('Save case record')}`,p=>mutate('police.update',{id,...p},'Case record saved for review.'));break;}
    case 'police-reference':{const r=state.reports.find(r=>r.id===id);modal('Record an issued reference',`<p>Enter a reference already issued by police. This app does not register or verify the FIR.</p><form><div class="form-grid">${field('Issued FIR / diary reference','reference',r.officialReference||'','text','required maxlength="200"')}${field('Police station','station',r.station||'','text','required maxlength="200"')}${field('Recording officer','officer',r.officer||'','text','required maxlength="200"')}<label class="check field full"><input type="checkbox" name="attestation" required> This reference was already issued through the official police process.</label></div>${formEnd('Save issued reference')}`,p=>mutate('police.reference',{id,...p,attestation:!!p.attestation},'Issued reference recorded; not independently verified.'));break;}
    case 'police-close':modal('Close this case in the workspace',`<form><label class="field">Closure note<textarea name="note" required maxlength="1500"></textarea></label>${formEnd('Close case')}`,p=>mutate('police.close',{id,...p},'Case closed. You can reopen it.'));break;
    case 'police-reopen':await mutate('police.reopen',{id},'Case reopened.');break;
    case 'police-export':{const r=state.reports.find(r=>r.id===id),i=state.incidents.find(i=>i.id===r.incidentId);const text=['HEALTH SOS — CASE DRAFT','For officer review. Not proof of FIR registration.','',`Case: ${r.id}`,`Incident: ${r.incidentId}`,`Location: ${i?.address||''}`,`Station: ${r.station||''}`,`Officer: ${r.officer||''}`,`Reported external reference: ${r.officialReference||'None'}`,'','SUMMARY',r.summary,'','FIR DRAFT / NOTES',r.firDraft||'', '', 'Saved in the preview workspace. No external police submission has been made.'].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download=r.id+'-case-draft.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
    case 'stock-scan':await mutate('stock.scan',{},'Stock checked; expiry quarantine and pending requests updated.');break;
    case 'dispense':modal('Record stock movement',`<p>Stock record only. This is not a prescription or treatment recommendation.</p><form>${field('Quantity','quantity',1,'number','min="1" max="10000" required')}${formEnd('Record stock movement')}`,p=>mutate('stock.dispense',{id,...p}));break;
    case 'approve-order':await mutate('order.approve',{id},'Supply request approved.');break;
    case 'receive':modal('Receive an approved new batch',`<p>New deliveries are recorded as a separate batch.</p><form><div class="form-grid">${field('New batch reference','batch','','text','required maxlength="80"')}${field('Expiry date','expiry','','date','required')}</div>${formEnd('Receive batch')}`,p=>mutate('order.receive',{id,...p}));break;
    case 'dispose':modal('Record workspace disposal',`<p>In deployment, only an authorised handler may complete collection and supply disposal evidence. This records a fictional certificate.</p><form>${field('Previewnstration certificate reference','certificate','','text','required maxlength="100"')}${formEnd('Save certificate')}`,p=>mutate('collection.complete',{id,...p}));break;
    case 'tariff':modal('Add or revise an agreement tariff',`<p>Use an existing code, state and agreement to create a new version. Existing claims keep their original snapshot. No official prices are changed.</p><form><div class="form-grid">${field('Service code','code','ER-ASSESS','text','required')}${field('Service name','name','Emergency assessment','text','required')}${field('Amount in INR','amount',500,'number','min="0" max="10000000" required')}${field('State / territory','state','Delhi','text','required')}<label class="field full">Participating agreement<input name="scheme" value="Workspace tariff" required></label></div>${formEnd('Save tariff version')}`,p=>mutate('tariff.save',p));break;
    case 'claim':{const ts=state.tariffs.filter(t=>!state.tariffs.some(n=>n.code===t.code&&n.state===t.state&&n.scheme===t.scheme&&n.version>t.version));modal('Create an agreement-based claim',`<p>The amount is taken from the selected workspace tariff version.</p><form><label class="field">Service / package<select name="tariffId">${options(ts.map(t=>[t.id,`${t.name} · ${money(t.amount)} · v${t.version}`]))}</select></label>${formEnd('Submit claim')}`,p=>mutate('claim.create',{incidentId:id,...p}));break;}
    case 'approve-claim':await mutate('claim.approve',{id},'Claim approved for settlement preview.');break;
    case 'settle':await mutate('settlement.run',{},'Weekly settlement batch recorded. No money moved.');break;
    case 'reset':modal('Reset this prototype?',`<p>This deletes all previewnstration journeys, requests and settlements in this sandbox. It does not affect any real institution.</p><form>${formEnd('Reset preview data')}`,async()=>{state=await store.reset();subtab='overview';render();toast('Prototype reset.');});break;
    case 'export':{const blob=new Blob([JSON.stringify({prototype:true,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='health-sos-preview-record.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
    case 'privacy':modal('Privacy & connections',`<p><strong>Real directory:</strong> addresses and hospital names come from OpenStreetMap. Availability is not verified.</p><p><strong>Preview workspaces:</strong> capacity reservations, ambulance assignments, police records, stock and payments are local previewnstration workflows. They do not contact an external hospital, police station or supplier. An in-app reservation is not external admission confirmation.</p><p><strong>Emergency response:</strong> use Call 112 to open your phone dialler. The app does not automatically contact emergency services.</p><p><strong>Your records:</strong> ${store.mode()==='sqlite'?'saved on the local SQLite server.':'saved in this browser.'} These workspaces are not verified professional accounts.</p><p><strong>Camera:</strong> images are checked in memory, not saved. Optional AI sends an image to the configured provider only after your permission. Image checks cannot diagnose injuries.</p><p><a href="https://operations.osmfoundation.org/policies/nominatim/" target="_blank" rel="noopener">Address-service usage policy</a> · address searches run only when you submit them, without autocomplete.</p>`);break;
    case 'camera-sample':{const c=document.createElement('canvas');c.width=640;c.height=480;const ctx=c.getContext('2d');ctx.fillStyle='#dfe9d8';ctx.fillRect(0,0,640,480);for(let y=0;y<10;y++)for(let x=0;x<14;x++){ctx.fillStyle=(x+y)%2?'#285e50':'#f1efdf';ctx.fillRect(20+x*42,20+y*40,40,38);}ctx.fillStyle='#fff';ctx.fillRect(50,160,540,150);ctx.fillStyle='#163d3a';ctx.font='bold 28px sans-serif';ctx.fillText('Synthetic camera test image',75,225);ctx.font='18px sans-serif';ctx.fillText('No patient or medical information',75,265);cameraImage=c.toDataURL('image/jpeg',.9);cameraResult=null;scene=null;render();break;}
    case 'camera-browser':{if(!cameraImage)throw Error('Select an image first.');el.disabled=true;el.textContent='Loading OpenCV WebAssembly…';try{cameraResult=await analyzeBrowser(cameraImage);render();toast('Real OpenCV.js processing completed in this browser.');}finally{if(el.isConnected)el.disabled=false;}break;}
    case 'camera-upload':$('#image-file').click();break;
    case 'camera-start':{const stage=$('#camera-stage');stage.innerHTML='<video id="camera-video" autoplay playsinline muted aria-label="Live camera preview"></video>';try{await startCamera($('#camera-video'));$('#camera-actions').innerHTML=btn('Capture frame','camera-capture','','primary')+btn('Stop camera','camera-stop');}catch(e){render();throw e;}break;}
    case 'camera-stop':stopCamera();render();break;
    case 'camera-capture':cameraImage=capture($('#camera-video'));stopCamera();cameraResult=null;scene=null;render();break;
    case 'camera-clear':stopCamera();cameraImage=null;cameraResult=null;scene=null;render();break;
    case 'camera-analyze':{if(!cameraImage)throw Error('Capture or upload an image first.');el.disabled=true;el.textContent='Running OpenCV…';try{if(store.mode()==='sqlite'){try{cameraResult=await store.cameraAnalyze(cameraImage);}catch(error){toast('Local Python engine unavailable. Running OpenCV in your browser instead.');cameraResult=await analyzeBrowser(cameraImage);}}else cameraResult=await analyzeBrowser(cameraImage);render();toast('OpenCV image-quality analysis complete. No clinical assessment made.');}finally{if(el.isConnected){el.disabled=false;el.textContent='Check image with OpenCV';}}break;}
    case 'camera-ai':{if(!cameraImage)throw Error('Capture or upload an image first.');if(!$('#ai-consent')?.checked)throw Error('Confirm permission before sharing the image with the AI provider.');el.disabled=true;try{const response=await store.describeScene(cameraImage);scene=response.description;$('#scene-description').textContent=scene;toast('AI description is unverified. Share observations with a qualified responder.');}finally{el.disabled=false;}break;}
    case 'speak':{if(!('speechSynthesis'in window))throw Error('Speech is unavailable in this browser.');speechSynthesis.cancel();const g=guidance(questions),utterance=new SpeechSynthesisUtterance(g.title+'. '+g.steps.join('. '));utterance.lang='en-IN';utterance.rate=.9;speechSynthesis.speak(utterance);break;}
  }
}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();navigate(nav.dataset.nav);return;}const el=e.target.closest('[data-do]');if(!el||busy)return;try{busy=true;await doAction(el.dataset.do,el);}catch(error){toast(error.message||'Something went wrong. Please retry.',true);try{state=await store.read();}catch{}}finally{busy=false;}});
document.addEventListener('change',async e=>{
  if(e.target.id==='facility'){activeHospitalId=e.target.value;render();return;}
  if(e.target.id==='role'){try{role=e.target.value;if(role==='hospital'&&state.incidents[0]?.hospitalId)activeHospitalId=state.incidents[0].hospitalId;await store.setRole(role);state=await store.read();subtab='overview';navigate(role==='patient'?'home':'dashboard');}catch(error){toast(error.message,true);}return;}
  if(e.target.closest('#questions')){questions=Object.fromEntries(new FormData($('#questions')));const g=guidance(questions);$('#guidance-title').textContent=g.title;$('#guidance-steps').innerHTML=g.steps.map(s=>`<li>${esc(s)}</li>`).join('');return;}
  if(e.target.id==='image-file'){try{cameraImage=await readImage(e.target.files[0]);cameraResult=null;scene=null;stopCamera();render();}catch(error){toast(error.message,true);}}
});
document.addEventListener('submit',async e=>{
 if(e.target.id==='address-form'){
  e.preventDefault();const p=Object.fromEntries(new FormData(e.target));addressQuery=p.query;addressContext=e.target.dataset.context;addressBusy=true;addressResults=[];render();
  try{addressResults=await store.searchAddress(addressQuery);if(!addressResults.length)throw Error('No matching address. Add your city or try a nearby landmark.');}catch(error){toast(error.message,true);}finally{addressBusy=false;render();}return;
 }
 if(e.target.id==='incident-form'){
  e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]');button.disabled=true;
  try{if(!coords)throw Error('Choose an address first.');const p=Object.fromEntries(new FormData(form));incidentKind=p.incidentType;await mutate('incident.create',{...p,lat:coords.lat,lon:coords.lon,address:locationLabel,autoRequest:true,preferredHospitalId:chosenHospitalId,consent:false},'Incident saved. View your destination and reservation status below.');navigate('journey');}catch(error){form.querySelector('.form-error').textContent=error.message;}finally{if(button.isConnected)button.disabled=false;}
 }
});
window.addEventListener('pagehide',()=>{stopCamera();if('speechSynthesis'in window)speechSynthesis.cancel();});
try{state=await store.init();const hash=location.hash.slice(1);if(['home','emergency','nearby','journey','request'].includes(hash))page=hash;try{const saved=JSON.parse(sessionStorage.getItem('health-sos-location')||'null');if(saved){coords={lat:saved.lat,lon:saved.lon};locationLabel=saved.label;addressQuery=saved.name||saved.label;const cached=JSON.parse(sessionStorage.getItem('health-sos-directory')||'null');if(cached&&cached.lat===coords.lat&&cached.lon===coords.lon){directoryMeta=cached;liveHospitals=cached.hospitals||[];}}}catch{}if(page==='request')requestStage=coords?2:1;render();poll=setInterval(refresh,4000);}catch(error){$('#app').innerHTML=`<main><h1>We couldn’t load your records.</h1><p>${esc(error.message)}</p><p>Allow site storage, or run the SQLite server with <code>npm start</code>.</p><button class="btn" onclick="location.reload()">Try again</button></main>`;}
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
